local byText
-- the description for an option, found by the words on it
function addon.OptionTip(text)
    if not byText then
        byText = {}
        for k, v in pairs(TIPS) do byText[L(k)] = v end
    end
    local v = byText[text] or TIPS[text]
    return v and L(v) or nil
end

